29	using SegmentID = uint32_t;
30	using BlockID = uint32_t;
31	
32	class BlockMeta {
33	 public:
34	  using Ptr = std::shared_ptr<BlockMeta>;
35	
36	 public:
37	  BlockMeta() = default;
38	
39	  BlockMeta(uint32_t id, BlockType type, uint64_t min_doc_id,
40	            uint64_t max_doc_id, uint32_t doc_count,
41	            const std::vector<std::string> &columns)
42	      : id_(id),
43	        type_(type),
44	        min_doc_id_(min_doc_id),
45	        max_doc_id_(max_doc_id),
46	        doc_count_(doc_count),
47	        columns_(columns) {}
48	
49	  BlockMeta(uint32_t id, BlockType type, uint64_t min_doc_id,
50	            uint64_t max_doc_id)
51	      : id_(id),
52	        type_(type),
53	        min_doc_id_(min_doc_id),
54	        max_doc_id_(max_doc_id) {}
55	  uint32_t id() const {
56	    return id_;
57	  }
58	
59	  void set_id(uint32_t id) {
60	    id_ = id;
61	  }
62	
63	  BlockType type() const {
64	    return type_;
65	  }
66	
67	  void set_type(BlockType type) {
68	    type_ = type;
69	  }
70	
71	  uint64_t min_doc_id() const {
72	    return min_doc_id_;
73	  }
74	
75	  void set_min_doc_id(uint64_t min_doc_id) {
76	    min_doc_id_ = min_doc_id;
77	  }
78	
79	  uint64_t max_doc_id() const {
80	    return max_doc_id_;
81	  }
82	
83	  void set_max_doc_id(uint64_t max_doc_id) {
84	    max_doc_id_ = max_doc_id;
85	  }
86	
87	  uint32_t doc_count() const {
88	    return doc_count_;
89	  }
90	
91	  void set_doc_count(uint32_t doc_count) {
92	    doc_count_ = doc_count;
93	  }
94	
95	  const std::vector<std::string> &columns() const {
96	    return columns_;
97	  }
98	
99	  void set_columns(const std::vector<std::string> &columns) {
100	    columns_ = columns;
101	  }
102	
103	  void add_column(const std::string &column) {
104	    columns_.push_back(column);
105	  }
106	
107	  void del_column(const std::string &column) {
108	    columns_.erase(std::remove(columns_.begin(), columns_.end(), column),
109	                   columns_.end());
110	  }
111	
112	  bool contain_column(const std::string &column) const {
113	    return std::find(columns_.begin(), columns_.end(), column) !=
114	           columns_.end();
115	  }
116	
117	 public:
118	  bool operator==(const BlockMeta &other) const {
119	    return id_ == other.id_ && type_ == other.type_ &&
120	           min_doc_id_ == other.min_doc_id_ &&
121	           max_doc_id_ == other.max_doc_id_ && columns_ == other.columns_ &&
122	           doc_count_ == other.doc_count_;
123	  }
124	
125	  std::string to_string() const {
126	    std::ostringstream oss;
127	    oss << "BlockMeta{"
128	        << "id:" << id_ << ",type:" << BlockTypeCodeBook::AsString(type_)
129	        << ",min_doc_id:" << min_doc_id_ << ",max_doc_id:" << max_doc_id_
130	        << ",doc_count:" << doc_count_ << ",columns:[";
131	
132	    for (size_t i = 0; i < columns_.size(); ++i) {
133	      if (i > 0) oss << ",";
134	      oss << "'" << columns_[i] << "'";
135	    }
136	
137	    oss << "]}";
138	    return oss.str();
139	  }
140	
141	  std::string to_string_formatted(int indent_level = 0) const {
142	    std::ostringstream oss;
143	    oss << indent(indent_level) << "BlockMeta{\n"
144	        << indent(indent_level + 1) << "id: " << id_ << ",\n"
145	        << indent(indent_level + 1)
146	        << "type: " << BlockTypeCodeBook::AsString(type_) << ",\n"
147	        << indent(indent_level + 1) << "min_doc_id: " << min_doc_id_ << ",\n"
148	        << indent(indent_level + 1) << "max_doc_id: " << max_doc_id_ << ",\n"
149	        << indent(indent_level + 1) << "doc_count: " << doc_count_ << ",\n"
150	        << indent(indent_level + 1) << "columns: [";
151	
152	    if (!columns_.empty()) {
153	      oss << "\n";
154	      for (size_t i = 0; i < columns_.size(); ++i) {
155	        oss << indent(indent_level + 2) << "'" << columns_[i] << "'";
156	        if (i < columns_.size() - 1) {
157	          oss << ",";
158	        }
159	        oss << "\n";
160	      }
161	      oss << indent(indent_level + 1);
162	    }
163	
164	    oss << "]\n" << indent(indent_level) << "}";
165	    return oss.str();
166	  }
167	
168	 public:
169	  uint32_t id_{0};
170	  BlockType type_{BlockType::UNDEFINED};
171	  uint64_t min_doc_id_{0};
172	  uint64_t max_doc_id_{0};
173	  uint32_t doc_count_{0};
174	  std::vector<std::string> columns_{};
175	};
176	
177	class SegmentMeta {
178	 public:
179	  using Ptr = std::shared_ptr<SegmentMeta>;
180	
181	 public:
182	  SegmentMeta() {};
183	
184	  explicit SegmentMeta(SegmentID id) : id_(id) {}
185	
186	  void set_id(SegmentID id) {
187	    id_ = id;
188	  }
189	
190	  SegmentID id() const {
191	    return id_;
192	  }
193	
194	  void add_persisted_block(const BlockMeta &block) {
195	    persisted_blocks_.push_back(block);
196	  }
197	
198	  void set_persisted_blocks(const std::vector<BlockMeta> &blocks) {
199	    persisted_blocks_ = blocks;
200	  }
201	
202	  bool remove_block(BlockID block_id) {
203	    auto it = std::remove_if(
204	        persisted_blocks_.begin(), persisted_blocks_.end(),
205	        [block_id](const BlockMeta &block) { return block.id() == block_id; });
206	    bool found = (it != persisted_blocks_.end());
207	    persisted_blocks_.erase(it, persisted_blocks_.end());
208	    return found;
209	  }
210	
211	  void remove_vector_persisted_block(const std::string &column, bool quantize) {
212	    std::vector<BlockMeta> new_persisted_blocks;
213	    for (auto &b : persisted_blocks_) {
214	      if (quantize) {
215	        if (!(b.type() == BlockType::VECTOR_INDEX_QUANTIZE &&
216	              b.contain_column(column))) {
217	          new_persisted_blocks.push_back(b);
218	        }
219	      } else {
220	        if (!(b.type() == BlockType::VECTOR_INDEX &&
221	              b.contain_column(column))) {
222	          new_persisted_blocks.push_back(b);
223	        }
224	      }
225	    }
226	    persisted_blocks_ = new_persisted_blocks;
227	  }
228	
229	  void remove_vector_persisted_block(const std::string &column) {
230	    std::vector<BlockMeta> new_persisted_blocks;
231	    for (auto &b : persisted_blocks_) {
232	      if (!b.contain_column(column)) {
233	        new_persisted_blocks.push_back(b);
234	      }
235	    }
236	    persisted_blocks_ = new_persisted_blocks;
237	  }
238	
239	  void remove_scalar_index_block() {
240	    std::vector<BlockMeta> new_persisted_blocks;
241	    for (auto &b : persisted_blocks_) {
242	      if (b.type() != BlockType::SCALAR_INDEX) {
243	        new_persisted_blocks.push_back(b);
244	      }
245	    }
246	    persisted_blocks_ = new_persisted_blocks;
247	  }
248	
249	  void remove_fts_index_block() {
250	    std::vector<BlockMeta> new_persisted_blocks;
251	    for (auto &b : persisted_blocks_) {
252	      if (b.type() != BlockType::FTS_INDEX) {
253	        new_persisted_blocks.push_back(b);
254	      }
255	    }
256	    persisted_blocks_ = new_persisted_blocks;
257	  }
258	
259	  void set_writing_forward_block(const BlockMeta &writing_forward_block) {
260	    writing_forward_block_ = writing_forward_block;
261	  }
262	
263	  void remove_writing_forward_block() {
264	    writing_forward_block_ = std::nullopt;
265	  }
266	
267	  void update_max_doc_id(uint64_t max_doc_id) {
268	    if (writing_forward_block_.has_value()) {
269	      writing_forward_block_->set_max_doc_id(max_doc_id);
270	    }
271	  }
272	
273	  uint64_t min_doc_id() const {
274	    if (persisted_blocks_.empty()) {
275	      if (writing_forward_block_.has_value()) {
276	        return writing_forward_block_->min_doc_id();
277	      }
278	      return 0;
279	    }
280	    uint64_t min_doc_id{std::numeric_limits<uint64_t>::max()};
281	    for (const auto &block : persisted_blocks_) {
282	      if (block.type() == BlockType::SCALAR) {
283	        min_doc_id = std::min(min_doc_id, block.min_doc_id());
284	      }
285	    }
286	    if (min_doc_id == std::numeric_limits<uint64_t>::max() &&
287	        writing_forward_block_.has_value()) {
288	      min_doc_id = writing_forward_block_->min_doc_id();
289	    }
290	    return min_doc_id;
291	  }
292	
293	  uint64_t max_doc_id() const {
294	    if (writing_forward_block_.has_value() &&
295	        writing_forward_block_->doc_count_ != 0) {
296	      return writing_forward_block_->max_doc_id();
297	    }
298	    uint64_t max_doc_id{0};
299	    for (const auto &block : persisted_blocks_) {
300	      if (block.type() == BlockType::SCALAR) {
301	        max_doc_id = std::max(max_doc_id, block.max_doc_id());
302	      }
303	    }
304	    return max_doc_id;
305	  }
306	
307	  uint32_t doc_count() const {
308	    uint32_t count{0};
309	    if (writing_forward_block_.has_value()) {
310	      count = writing_forward_block_->doc_count();
311	    }
312	    for (const auto &block : persisted_blocks_) {
313	      if (block.type() == BlockType::SCALAR) {
314	        count += block.doc_count();
315	      }
316	    }
317	    return count;
318	  }
319	
320	  std::vector<BlockMeta> &persisted_blocks() {
321	    return persisted_blocks_;
322	  }
323	
324	  const std::vector<BlockMeta> &persisted_blocks() const {
325	    return persisted_blocks_;
326	  }
327	
328	  std::optional<BlockMeta> &writing_forward_block() {
329	    return writing_forward_block_;
330	  }
331	
332	  const std::optional<BlockMeta> &writing_forward_block() const {
333	    return writing_forward_block_;
334	  }
335	
336	  bool has_writing_forward_block() const {
337	    return writing_forward_block_.has_value();
338	  }
339	
340	  bool vector_indexed(const std::string &field) const {
341	    return indexed_vector_fields_.count(field) > 0;
342	  }
343	
344	  void add_indexed_vector_field(const std::string &field) {
345	    indexed_vector_fields_.insert(field);
346	  }
347	
348	  std::set<std::string> indexed_vector_fields() const {
349	    return indexed_vector_fields_;
350	  }
351	
352	  void set_indexed_vector_fields(const std::set<std::string> &fields) {
353	    indexed_vector_fields_ = fields;
354	  }
355	
356	 public:
357	  bool operator==(const SegmentMeta &other) const {
358	    return id_ == other.id_ && persisted_blocks_ == other.persisted_blocks_ &&
359	           writing_forward_block_ == other.writing_forward_block_ &&
360	           indexed_vector_fields_ == other.indexed_vector_fields_;
361	  }
362	
363	  bool operator!=(const SegmentMeta &other) const {
364	    return !(*this == other);
365	  }
366	
367	  // Add these methods to SegmentMeta class in meta.h
368	
369	  std::string to_string() const {
370	    std::ostringstream oss;
371	    oss << "SegmentMeta{"
372	        << "id:" << id_ << ",persisted_blocks:[";
373	
374	    for (size_t i = 0; i < persisted_blocks_.size(); ++i) {
375	      if (i > 0) oss << ",";
376	      oss << persisted_blocks_[i].to_string();
377	    }
378	
379	    oss << "],writing_forward_block:";
380	    if (writing_forward_block_.has_value()) {
381	      oss << writing_forward_block_->to_string();
382	    } else {
383	      oss << "null";
384	    }
385	
386	    oss << ",indexed_vector_fields:[";
387	
388	    size_t i = 0;
389	    for (const auto &field : indexed_vector_fields_) {
390	      if (i > 0) oss << ",";
391	      oss << "'" << field << "'";
392	      ++i;
393	    }
394	
395	    oss << "]}";
396	    return oss.str();
397	  }
398	
399	  std::string to_string_formatted(int indent_level = 0) const {
400	    std::ostringstream oss;
401	    oss << indent(indent_level) << "SegmentMeta{\n"
402	        << indent(indent_level + 1) << "id: " << id_ << ",\n"
403	        << indent(indent_level + 1) << "persisted_blocks: [\n";
404	
405	    for (size_t i = 0; i < persisted_blocks_.size(); ++i) {
406	      oss << persisted_blocks_[i].to_string_formatted(indent_level + 2);
407	      if (i < persisted_blocks_.size() - 1) {
408	        oss << ",";
409	      }
410	      oss << "\n";
411	    }
412	
413	    oss << "\n"
414	        << indent(indent_level + 1) << "],\n"
415	        << indent(indent_level + 1) << "writing_forward_block: ";
416	
417	    if (writing_forward_block_.has_value()) {
418	      oss << "\n"
419	          << writing_forward_block_->to_string_formatted(indent_level + 2)
420	          << "\n";
421	    } else {
422	      oss << "null\n";
423	    }
424	
425	    oss << indent(indent_level + 1) << "indexed_vector_fields: [";
426	
427	    size_t i = 0;
428	    for (const auto &field : indexed_vector_fields_) {
429	      if (i > 0) oss << ",";
430	      oss << "'" << field << "'";
431	      ++i;
432	    }
433	
434	    oss << "]\n" << indent(indent_level) << "}";
435	    return oss.str();
436	  }
437	
438	 private:
439	  SegmentID id_{0};
440	  std::vector<BlockMeta> persisted_blocks_;
441	  std::optional<BlockMeta> writing_forward_block_;
442	  std::set<std::string> indexed_vector_fields_;
443	};
444	
445	}  // namespace zvec

